-- WASSCE Economics 2023 Questions (50 questions)

INSERT OR IGNORE INTO past_papers (id, exam_type_id, subject_id, paper_type_id, year, month, total_questions, total_marks, time_allowed, is_complete)
VALUES ('pp_wassce_eco_2023_1', 'exam_wassce', 'subj_wassce_economics', 'paper_wassce_1', 2023, 'May-June', 50, 50, 60, 1);

INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Basic Economic Concepts (1-10)
('q_eco_2023_001', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Economics is best defined as the study of:', 'multiple_choice', '["A. Money and banking", "B. How society allocates scarce resources", "C. Government spending", "D. Business management"]', 'B', 'Economics studies how societies allocate limited resources to satisfy unlimited wants.', 'easy', 1, 1),
('q_eco_2023_002', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The basic economic problem arises because:', 'multiple_choice', '["A. Resources are unlimited", "B. Wants are limited", "C. Resources are scarce and wants are unlimited", "D. There is no government intervention"]', 'C', 'Scarcity occurs because resources are limited while human wants are unlimited.', 'easy', 1, 2),
('q_eco_2023_003', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Opportunity cost is:', 'multiple_choice', '["A. The total cost of production", "B. The money spent on goods", "C. The next best alternative forgone", "D. The cost of raw materials"]', 'C', 'Opportunity cost is the value of the next best alternative that is sacrificed when making a choice.', 'easy', 1, 3),
('q_eco_2023_004', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The Production Possibility Frontier (PPF) shows:', 'multiple_choice', '["A. Consumer preferences", "B. Maximum output combinations with given resources", "C. Import and export balance", "D. Government budget"]', 'B', 'The PPF shows the maximum combinations of goods that can be produced with available resources.', 'medium', 1, 4),
('q_eco_2023_005', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Which is NOT a factor of production?', 'multiple_choice', '["A. Land", "B. Labor", "C. Money", "D. Capital"]', 'C', 'The factors of production are land, labor, capital, and entrepreneurship. Money is a medium of exchange.', 'easy', 1, 5),
('q_eco_2023_006', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Division of labor refers to:', 'multiple_choice', '["A. Sharing profits", "B. Splitting work into specialized tasks", "C. Dividing land", "D. Separating capital"]', 'B', 'Division of labor involves breaking down production into specialized tasks performed by different workers.', 'easy', 1, 6),
('q_eco_2023_007', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A mixed economy is characterized by:', 'multiple_choice', '["A. Only private ownership", "B. Only government ownership", "C. Both private and public sector participation", "D. No economic planning"]', 'C', 'A mixed economy combines elements of both market and command economies.', 'easy', 1, 7),
('q_eco_2023_008', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Capital goods are used to:', 'multiple_choice', '["A. Satisfy immediate wants", "B. Produce other goods", "C. Export only", "D. Pay wages"]', 'B', 'Capital goods are used in the production of other goods and services.', 'easy', 1, 8),
('q_eco_2023_009', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The reward for entrepreneurship is:', 'multiple_choice', '["A. Wages", "B. Rent", "C. Interest", "D. Profit"]', 'D', 'Entrepreneurs receive profit as the reward for risk-taking and organizing production.', 'easy', 1, 9),
('q_eco_2023_010', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Normative economics deals with:', 'multiple_choice', '["A. Facts and data", "B. What ought to be", "C. Historical trends", "D. Statistical analysis"]', 'B', 'Normative economics involves value judgments about what economic policies ought to be.', 'medium', 1, 10),

-- Demand, Supply, and Price (11-20)
('q_eco_2023_011', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The law of demand states that:', 'multiple_choice', '["A. Price and quantity demanded move together", "B. Higher prices lead to lower quantity demanded, ceteris paribus", "C. Supply creates its own demand", "D. Demand is constant"]', 'B', 'The law of demand: as price rises, quantity demanded falls, all other things being equal.', 'easy', 1, 11),
('q_eco_2023_012', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A movement along the demand curve is caused by:', 'multiple_choice', '["A. Change in income", "B. Change in tastes", "C. Change in price of the good", "D. Change in population"]', 'C', 'A movement along the curve is caused by a change in the price of the good itself.', 'easy', 1, 12),
('q_eco_2023_013', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'If demand is price inelastic, a price increase will:', 'multiple_choice', '["A. Decrease total revenue", "B. Increase total revenue", "C. Not affect total revenue", "D. Double the quantity demanded"]', 'B', 'With inelastic demand, price increases lead to higher total revenue as quantity falls proportionally less.', 'medium', 1, 13),
('q_eco_2023_014', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Complementary goods are goods that:', 'multiple_choice', '["A. Can substitute for each other", "B. Are used together", "C. Are luxury items", "D. Have no relation"]', 'B', 'Complementary goods are consumed together, like cars and fuel.', 'easy', 1, 14),
('q_eco_2023_015', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The equilibrium price is determined where:', 'multiple_choice', '["A. Demand exceeds supply", "B. Supply exceeds demand", "C. Demand equals supply", "D. Price is highest"]', 'C', 'Equilibrium price occurs where quantity demanded equals quantity supplied.', 'easy', 1, 15),
('q_eco_2023_016', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A price ceiling set below equilibrium will cause:', 'multiple_choice', '["A. Surplus", "B. Shortage", "C. Equilibrium", "D. Increased production"]', 'B', 'A price ceiling below equilibrium creates shortage as quantity demanded exceeds quantity supplied.', 'medium', 1, 16),
('q_eco_2023_017', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Cross elasticity of demand measures responsiveness of demand to:', 'multiple_choice', '["A. Income changes", "B. Price changes of related goods", "C. Own price changes", "D. Supply changes"]', 'B', 'Cross elasticity measures how demand for one good responds to price changes of another good.', 'medium', 1, 17),
('q_eco_2023_018', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Normal goods have:', 'multiple_choice', '["A. Negative income elasticity", "B. Zero income elasticity", "C. Positive income elasticity", "D. Infinite income elasticity"]', 'C', 'Normal goods have positive income elasticity - demand increases as income rises.', 'medium', 1, 18),
('q_eco_2023_019', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A rightward shift in the supply curve indicates:', 'multiple_choice', '["A. Decrease in supply", "B. Increase in supply", "C. Movement along the curve", "D. Change in demand"]', 'B', 'A rightward shift means more is supplied at every price level - an increase in supply.', 'easy', 1, 19),
('q_eco_2023_020', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Price elasticity of supply is likely to be higher when:', 'multiple_choice', '["A. Time period is short", "B. Time period is long", "C. Resources are fixed", "D. Technology is outdated"]', 'B', 'Supply is more elastic over longer time periods as producers can adjust capacity.', 'medium', 1, 20),

-- Market Structures (21-28)
('q_eco_2023_021', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Perfect competition is characterized by:', 'multiple_choice', '["A. Few sellers", "B. Many buyers and sellers with homogeneous products", "C. Product differentiation", "D. Barriers to entry"]', 'B', 'Perfect competition has many firms, identical products, and free entry/exit.', 'easy', 1, 21),
('q_eco_2023_022', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A monopoly exists when:', 'multiple_choice', '["A. There are many sellers", "B. There is only one seller", "C. Products are identical", "D. Entry is free"]', 'B', 'A monopoly has a single seller controlling the entire market.', 'easy', 1, 22),
('q_eco_2023_023', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Oligopoly is a market structure with:', 'multiple_choice', '["A. One seller", "B. Many sellers", "C. Few dominant sellers", "D. Perfect competition"]', 'C', 'Oligopoly has few large firms that dominate the market.', 'easy', 1, 23),
('q_eco_2023_024', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Monopolistic competition differs from perfect competition because:', 'multiple_choice', '["A. There are fewer firms", "B. Products are differentiated", "C. There is only one firm", "D. Prices are fixed by government"]', 'B', 'Monopolistic competition has many firms but with differentiated products.', 'medium', 1, 24),
('q_eco_2023_025', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A cartel is formed when firms:', 'multiple_choice', '["A. Compete aggressively", "B. Agree to fix prices or output", "C. Lower prices", "D. Exit the market"]', 'B', 'A cartel is a formal agreement among firms to coordinate prices or production.', 'medium', 1, 25),
('q_eco_2023_026', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'In perfect competition, firms are price:', 'multiple_choice', '["A. Makers", "B. Takers", "C. Setters", "D. Controllers"]', 'B', 'In perfect competition, individual firms are price takers - they accept the market price.', 'easy', 1, 26),
('q_eco_2023_027', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Natural monopoly occurs when:', 'multiple_choice', '["A. Government grants exclusive rights", "B. One firm can supply at lowest cost", "C. There are no substitutes", "D. Demand is very high"]', 'B', 'Natural monopoly exists when one firm can supply the entire market more efficiently than multiple firms.', 'medium', 1, 27),
('q_eco_2023_028', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Price discrimination requires:', 'multiple_choice', '["A. Perfect competition", "B. Market power and ability to segment markets", "C. Free entry", "D. Homogeneous products"]', 'B', 'Price discrimination requires market power and ability to prevent resale between market segments.', 'hard', 1, 28),

-- Money, Banking, and Finance (29-35)
('q_eco_2023_029', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The functions of money include all EXCEPT:', 'multiple_choice', '["A. Medium of exchange", "B. Store of value", "C. Factor of production", "D. Unit of account"]', 'C', 'Money functions as medium of exchange, store of value, unit of account, and standard of deferred payment.', 'easy', 1, 29),
('q_eco_2023_030', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The central bank of Ghana is:', 'multiple_choice', '["A. Ghana Commercial Bank", "B. Bank of Ghana", "C. Barclays Bank", "D. Ecobank"]', 'B', 'The Bank of Ghana is the central bank of Ghana, responsible for monetary policy.', 'easy', 1, 30),
('q_eco_2023_031', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Commercial banks create money through:', 'multiple_choice', '["A. Printing currency", "B. Credit creation", "C. Taxation", "D. Government grants"]', 'B', 'Commercial banks create money by making loans, which become deposits and can be lent again.', 'medium', 1, 31),
('q_eco_2023_032', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Open market operations involve:', 'multiple_choice', '["A. Setting interest rates", "B. Buying and selling government securities", "C. Printing money", "D. Setting reserve requirements"]', 'B', 'Open market operations involve central bank buying or selling government securities to control money supply.', 'medium', 1, 32),
('q_eco_2023_033', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Inflation is defined as:', 'multiple_choice', '["A. Decrease in prices", "B. Sustained increase in general price level", "C. Increase in output", "D. Decrease in money supply"]', 'B', 'Inflation is a persistent rise in the general level of prices over time.', 'easy', 1, 33),
('q_eco_2023_034', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Cost-push inflation is caused by:', 'multiple_choice', '["A. Increased demand", "B. Rising production costs", "C. Lower interest rates", "D. Government spending"]', 'B', 'Cost-push inflation occurs when rising input costs push up prices.', 'medium', 1, 34),
('q_eco_2023_035', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The exchange rate is the price of:', 'multiple_choice', '["A. Goods in the domestic market", "B. One currency in terms of another", "C. Government bonds", "D. Stocks and shares"]', 'B', 'Exchange rate is the rate at which one currency can be exchanged for another.', 'easy', 1, 35),

-- Government and the Economy (36-42)
('q_eco_2023_036', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Fiscal policy involves the use of:', 'multiple_choice', '["A. Interest rates", "B. Government spending and taxation", "C. Money supply", "D. Exchange rates"]', 'B', 'Fiscal policy uses government spending and taxation to influence the economy.', 'easy', 1, 36),
('q_eco_2023_037', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A progressive tax is one where:', 'multiple_choice', '["A. Everyone pays the same amount", "B. Tax rate increases with income", "C. Tax rate decreases with income", "D. Tax is based on wealth only"]', 'B', 'Progressive taxation means higher income earners pay a higher percentage of their income.', 'easy', 1, 37),
('q_eco_2023_038', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Public goods are characterized by:', 'multiple_choice', '["A. Excludability and rivalry", "B. Non-excludability and non-rivalry", "C. High prices", "D. Private provision only"]', 'B', 'Public goods are non-excludable and non-rivalrous, like national defense.', 'medium', 1, 38),
('q_eco_2023_039', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A budget deficit occurs when:', 'multiple_choice', '["A. Revenue exceeds expenditure", "B. Expenditure exceeds revenue", "C. Revenue equals expenditure", "D. There is no taxation"]', 'B', 'Budget deficit means government spending exceeds its revenue.', 'easy', 1, 39),
('q_eco_2023_040', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Externalities are:', 'multiple_choice', '["A. Internal costs", "B. Third-party effects not reflected in market prices", "C. Government regulations", "D. Private benefits"]', 'B', 'Externalities are costs or benefits affecting parties not directly involved in a transaction.', 'medium', 1, 40),
('q_eco_2023_041', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Privatization means:', 'multiple_choice', '["A. Government takeover of private firms", "B. Transfer of state enterprises to private ownership", "C. Nationalization", "D. Increasing government control"]', 'B', 'Privatization involves selling state-owned enterprises to private investors.', 'easy', 1, 41),
('q_eco_2023_042', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'GDP measures:', 'multiple_choice', '["A. Total imports", "B. Total value of goods and services produced", "C. Government debt", "D. Foreign investment only"]', 'B', 'GDP is the total value of all goods and services produced within a country in a given period.', 'easy', 1, 42),

-- International Trade (43-50)
('q_eco_2023_043', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Comparative advantage is based on:', 'multiple_choice', '["A. Absolute cost differences", "B. Relative opportunity costs", "C. Exchange rates", "D. Population size"]', 'B', 'Comparative advantage means producing goods at lower opportunity cost relative to trading partners.', 'medium', 1, 43),
('q_eco_2023_044', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A tariff is:', 'multiple_choice', '["A. A subsidy on exports", "B. A tax on imports", "C. A quota on production", "D. A trade agreement"]', 'B', 'A tariff is a tax imposed on imported goods.', 'easy', 1, 44),
('q_eco_2023_045', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'The balance of trade is the difference between:', 'multiple_choice', '["A. Assets and liabilities", "B. Exports and imports of goods", "C. Income and expenditure", "D. Savings and investment"]', 'B', 'Balance of trade = value of exports - value of imports of goods.', 'easy', 1, 45),
('q_eco_2023_046', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'ECOWAS stands for:', 'multiple_choice', '["A. East African Economic Community", "B. Economic Community of West African States", "C. European Community of Western States", "D. Economic Council of World States"]', 'B', 'ECOWAS is the Economic Community of West African States, promoting regional integration.', 'easy', 1, 46),
('q_eco_2023_047', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Dumping occurs when:', 'multiple_choice', '["A. Goods are sold at low quality", "B. Goods are sold below cost in foreign markets", "C. Goods are recycled", "D. Goods are imported cheaply"]', 'B', 'Dumping is selling goods in foreign markets below production cost or domestic price.', 'medium', 1, 47),
('q_eco_2023_048', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'A quota is:', 'multiple_choice', '["A. A tax on imports", "B. A limit on quantity of imports", "C. A type of subsidy", "D. An exchange rate"]', 'B', 'A quota is a quantitative restriction on the amount of a good that can be imported.', 'easy', 1, 48),
('q_eco_2023_049', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Currency appreciation means:', 'multiple_choice', '["A. Currency loses value", "B. Currency gains value against others", "C. Inflation increases", "D. Interest rates fall"]', 'B', 'Appreciation means a currency increases in value relative to other currencies.', 'easy', 1, 49),
('q_eco_2023_050', 'subj_wassce_economics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_eco_2023_1', 'Terms of trade refers to:', 'multiple_choice', '["A. Trade agreements", "B. Ratio of export prices to import prices", "C. Trade barriers", "D. Trade balance"]', 'B', 'Terms of trade = (index of export prices / index of import prices) × 100.', 'medium', 1, 50);
